// apply-halaman.mjs — Bangun halaman Profil/Pojok Media dari DB:
//   Berita, Berita Utama, Organisasi, Capability, Personil, JDQ, Kerja Sama, Fasilitas.
// PRASYARAT: jalankan SETELAH apply-dinamis, apply-navbar, apply-navbar-visual, apply-fixes.
// Cara pakai (dari root project):
//     node apply-halaman.mjs
//     npm run dev       (atau: npm run build && node build)
// Kalau route baru 404 → stop lalu start ulang dev server (SvelteKit perlu re-scan route).
// Aman dijalankan berkali-kali.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ["src/lib/server/db/schema.ts", ''],
  ["src/lib/types/content.ts", ''],
  ["src/lib/server/portal/transform.ts", ''],
  ["src/lib/server/portal/queries.ts", ''],
  ["src/lib/data/nav.ts", ''],
  ["src/lib/components/shared/rich-content.svelte", ''],
  ["src/lib/components/shared/personil-table.svelte", ''],
  ["src/routes/personil/+page.server.ts", ''],
  ["src/routes/personil/+page.svelte", ''],
  ["src/routes/berita/+page.server.ts", ''],
  ["src/routes/berita/+page.svelte", ''],
  ["src/routes/berita-utama/+page.server.ts", ''],
  ["src/routes/berita-utama/+page.svelte", ''],
  ["src/routes/organisasi/+page.server.ts", ''],
  ["src/routes/organisasi/+page.svelte", ''],
  ["src/routes/capability/+page.server.ts", ''],
  ["src/routes/capability/+page.svelte", ''],
  ["src/routes/kerjasama/+page.server.ts", ''],
  ["src/routes/kerjasama/+page.svelte", ''],
  ["src/routes/jdq/+page.server.ts", ''],
  ["src/routes/jdq/+page.svelte", ''],
  ["src/routes/fasilitas/+page.server.ts", ''],
  ["src/routes/fasilitas/+page.svelte", ''],
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  ditulis:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL  :', path, '-', e.message);
  }
}
console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file ditulis.');
console.log('Restart dev server (WAJIB, karena ada route baru): npm run dev');
console.log('Halaman baru: /berita /berita-utama /organisasi /capability /personil /jdq /kerjasama /fasilitas');
console.log('Menu navbar sudah otomatis diarahkan ke halaman-halaman ini.');
